typedef unsigned char u_char;
typedef unsigned short u_short;
typedef unsigned int u_int;
typedef unsigned long long u_long;
extern "C" char *strncpy(char *, const char *, u_int);
extern "C" char *strlwr(char *);
extern "C" void *memset(void *, int, u_int);

class nglFixedString
{
public:
  typedef u_long fint;
  enum { FINT_SIZE = 8, STR_SIZE = 32, NUM_FINTS = 4 };
  typedef nglFixedString FS;
  fint *value() { return reinterpret_cast<fint *>(str); }
  const fint *value() const { return reinterpret_cast<const fint *>(str); }
  nglFixedString(const FS &s) { for (int i = 0; i < NUM_FINTS; ++i) value()[i] = s.value()[i]; }
  nglFixedString(const char *s) { for (int i = 0; i < NUM_FINTS; ++i) value()[i] = 0; strncpy(str, s, STR_SIZE - 1); strlwr(str); }
  const FS &operator=(const FS &rhs) { for (int i = 0; i < NUM_FINTS; ++i) value()[i] = rhs.value()[i]; return *this; }
  const char *c_str() const { return str; }
private:
  char str[STR_SIZE];
} __attribute__((aligned(8)));
typedef nglFixedString atestring;

struct nglTexStreamPos { u_int addr, cycle; };
struct nglFileBuf { u_char *Buf; u_int Size; u_int UserData; };
struct nglTexture
{
  nglTexStreamPos TexStreamPos;
  u_short Width, Height;
  u_int Hash;
  u_char Type, TW, TH;
  struct { u_int LoadedInPlace:1; u_int Locked:1; u_int VRAMOnly:1; u_int System:1; u_int RenderTarget:1; } Flags;
  void *ph;
  u_int Format;
  u_int *Data;
  u_int NFrames;
  nglTexture **Frames;
  u_int SrcDataSize;
  nglFileBuf FileBuf;
  nglFixedString FileName;
  char remaining[208];
};
class nglInstanceBank { public: struct Instance; Instance *Insert(const nglFixedString &, void *); };
enum { NGLTEX_TGA, NGLTEX_TIM2, NGLTEX_IFL, NGLTEX_ATE };
extern u_int nglDisableTim2Conversion;
extern nglInstanceBank nglTextureBank;
extern bool ATEHeaderValid(char *);
extern u_int ATETextureCount(char *, const atestring &);
extern atestring &ATETextureName(char *, const atestring &, int);
extern char *ATETextureHeader(char *, const atestring &, int);
extern char *ATETextureImage(char *, const atestring &, int);
extern char *ATETexturePalette(char *, const atestring &, int);
extern void *nglMemAlloc(u_int, u_int = 1);
extern bool nglLoadTextureSplitTM2(nglTexture *, u_char *, u_char *, u_char *);

bool nglLoadTextureATE( nglTexture* Tex, unsigned char *Buf, const nglFixedString &FileName )
{
  atestring ps = atestring( FileName.c_str() );

  if ( !ATEHeaderValid((char *)Buf) )
    return false;

  u_int Temp = nglDisableTim2Conversion;
  nglDisableTim2Conversion = 1;

  Tex->Type = NGLTEX_ATE;
  Tex->NFrames = ATETextureCount( (char *)Buf, ps );
  if ( Tex->NFrames <= 0 )
  {
    nglDisableTim2Conversion = Temp;
    return false;
  }

  Tex->Frames = (nglTexture**)nglMemAlloc( sizeof(nglTexture*) * Tex->NFrames );
  for ( u_int i=0; i<Tex->NFrames; i++ )
  {
    nglFixedString nam( ATETextureName( (char *)Buf, ps, i ).c_str() );
    u_char *hed=(u_char *) ATETextureHeader( (char *)Buf,ps, i );
    u_char *img=(u_char *) ATETextureImage( (char *)Buf,ps, i );
    u_char *pal=(u_char *) ATETexturePalette( (char *)Buf,ps, i );
    Tex->Frames[i] = (nglTexture*) nglMemAlloc( sizeof(nglTexture));
    memset( Tex->Frames[i], 0, sizeof(nglTexture) );
    nglLoadTextureSplitTM2(Tex->Frames[i],hed,img,pal);
    Tex->Frames[i]->FileName = nam;
   	Tex->Frames[i]->Flags.LoadedInPlace=true;

	nglTextureBank.Insert( Tex->Frames[i]->FileName, Tex->Frames[i] );
  }

  Tex->Data=(unsigned int *)Buf;

  nglDisableTim2Conversion = Temp;
  return true;
}
